llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Alprazolam, a 7-chloro-5-phenyl-1,4-benzodiazepine with a fused triazole, has reported oral bioavailability of 92% in humans, supporting high F for the closely related benzodiazepine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Estazolam, another 7-chloro-5-phenyl benzodiazepine, showed 87% oral bioavailability in healthy volunteers after a 4 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Clobazam, a 1,5-benzodiazepine, is reported to have 90-100% oral bioavailability in humans, indicating high F for benzodiazepine structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Adinazolam, a triazolobenzodiazepine closely related to alprazolam, had absolute oral bioavailability of 39% in healthy male volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Triazolam, a triazolobenzodiazepine with a 2-chlorophenyl group, has absolute oral bioavailability of approximately 45-50% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a chlordiazepoxide-like 1,4-benzodiazepine N-oxide. Multiple close benzodiazepine analogs (alprazolam, estazolam, clobazam, adinazolam, triazolam) have oral bioavailability values from about 39% to 100%, all above the 20% threshold; no transferable low-F evidence applies. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "N-oxide and amidine metabolic stability are not directly assessed in the evidence set.",
    "Triazolam F values vary (30-85%) but remain above the 20% threshold.",
    "Low-F comparators (zotepine, lubiprostone) are structurally distant and not transferable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

